-- composition of rule kernels distinct_aggregate_rewrite x partitioned_execution (duckdb), template not_exists
SELECT count(*) FROM (SELECT DISTINCT 10::bigint AS c0, a1.c0 AS c1 FROM tl AS a1) AS ka WHERE NOT EXISTS (SELECT 1 FROM (SELECT '2000-01-01 00:00:00+00'::timestamptz AS c0, 1.5::numeric AS c1, (- CASE WHEN FALSE THEN (SELECT SUM (DISTINCT a2.c1) FROM t2 AS a2) ELSE 2.25::numeric END) AS c2, 10 AS c3 FROM t1 AS a1) AS kb);
-- pgfuzz:check kernel:not_exists SELECT CASE WHEN (SELECT count(*) FROM (SELECT '2000-01-01 00:00:00+00'::timestamptz AS c0, 1.5::numeric AS c1, (- CASE WHEN FALSE THEN (SELECT SUM (DISTINCT a2.c1) FROM t2 AS a2) ELSE 2.25::numeric END) AS c2, 10 AS c3 FROM t1 AS a1) AS kb) = 0 THEN (SELECT count(*) FROM (SELECT DISTINCT 10::bigint AS c0, a1.c0 AS c1 FROM tl AS a1) AS ka) ELSE 0 END
